  ZimmIcon: (props: { 'aria-label'?: string; 'aria-hidden'?: boolean }) => (
    <span aria-label={props['aria-label']} aria-hidden={props['aria-hidden']} />
  ),
}));

// The real modal's focus-trap/portal mechanics are already covered by useZimmModal.test.tsx
// (synthetic harness) and footer/index.stories.tsx's SubscribeModalOpen play (mutation-tested,
// real browser). Stubbing it here keeps this suite scoped to ZimmSubscribeSection's own
// contract — does it wire the right props into its children — rather than a second copy of
// coverage that already exists elsewhere.
vi.mock('app/components/ui-kits/organisms/zimmSubscribeModal', () => ({
  ZimmSubscribeModal: ({
    isOpen,
    onClose,
    onSubmit,
  }: {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (firstName: string, lastName: string) => void;
  }) =>
    isOpen ? (
      <div role="dialog" aria-label="mock subscribe modal">
        <button onClick={() => onSubmit('Jane', 'Smith')}>mock-continue</button>
        <button onClick={onClose}>mock-cancel</button>
      </div>
    ) : null,
}));


